import{_ as a,o,c as r,a0 as i}from"./chunks/framework.DScjKhBS.js";const u=JSON.parse('{"title":"nWave vs Superpowers","description":"Comparative technical research on two agentic development methodologies.","frontmatter":{"layout":"doc","title":"nWave vs Superpowers","description":"Comparative technical research on two agentic development methodologies."},"headers":[],"relativePath":"reports/agentic-framework-comparison/index.md","filePath":"reports/agentic-framework-comparison/index.md"}'),t={name:"reports/agentic-framework-comparison/index.md"};function n(s,e,l,c,d,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="nwave-vs-superpowers-comparative-research" tabindex="-1">nWave vs Superpowers: Comparative Research <a class="header-anchor" href="#nwave-vs-superpowers-comparative-research" aria-label="Permalink to &quot;nWave vs Superpowers: Comparative Research&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Leadership one-pager</strong></td><td><a href="./reports/agentic-framework-comparison/00-executive-summary.html">Executive summary &amp; decision matrix</a></td></tr></tbody></table><h2 id="research-objective" tabindex="-1">Research objective <a class="header-anchor" href="#research-objective" aria-label="Permalink to &quot;Research objective&quot;">​</a></h2><p>This document compares two prominent agentic development approaches:</p><ul><li><code>nWave</code> (<a href="https://github.com/nWave-ai/nWave/tree/main" target="_blank" rel="noreferrer">GitHub</a>, <a href="https://nwave.ai" target="_blank" rel="noreferrer">website</a>)</li><li><code>Superpowers</code> (<a href="https://github.com/obra/superpowers" target="_blank" rel="noreferrer">GitHub</a>, <a href="https://blog.fsck.com/2025/10/09/superpowers/" target="_blank" rel="noreferrer">launch article</a>)</li></ul><p>The focus is practical engineering behavior: workflow shape, control mechanisms, quality enforcement, operational overhead, and where each approach fits best.</p><h2 id="method-and-scope" tabindex="-1">Method and scope <a class="header-anchor" href="#method-and-scope" aria-label="Permalink to &quot;Method and scope&quot;">​</a></h2><ul><li>Primary sources reviewed: both repositories&#39; READMEs and the Superpowers launch write-up.</li><li>Analysis lens: process architecture, governance model, human control points, quality controls, portability, and team adoption risk.</li><li>This is an external comparative reading, not a benchmark from controlled execution tests.</li></ul><h2 id="approach-snapshots" tabindex="-1">Approach snapshots <a class="header-anchor" href="#approach-snapshots" aria-label="Permalink to &quot;Approach snapshots&quot;">​</a></h2><h3 id="nwave-pipeline-first-agentic-framework" tabindex="-1">nWave (pipeline-first agentic framework) <a class="header-anchor" href="#nwave-pipeline-first-agentic-framework" aria-label="Permalink to &quot;nWave (pipeline-first agentic framework)&quot;">​</a></h3><p>nWave defines a <strong>seven-wave delivery pipeline</strong> (<code>DISCOVER</code>, <code>DIVERGE</code>, <code>DISCUSS</code>, <code>DESIGN</code>, <code>DEVOPS</code>, <code>DISTILL</code>, <code>DELIVER</code>) where each wave produces artifacts, then requires human review/approval before moving forward.</p><p>Key structural characteristics:</p><ul><li>Explicit stage routing by context (greenfield, brownfield, bugfix, refactor).</li><li>Large role taxonomy (wave agents, specialists, reviewers, business agents).</li><li>Strong process enforcement through <code>DES</code> hook controls, including TDD phase checks and write restrictions during deliver sessions.</li><li>Adjustable rigor profiles (<code>lean</code> to <code>exhaustive</code>) to balance quality depth vs token cost.</li><li>Installation preference is CLI-based due to hook constraints in plugin-only mode.</li></ul><h3 id="superpowers-skill-first-orchestration-methodology" tabindex="-1">Superpowers (skill-first orchestration methodology) <a class="header-anchor" href="#superpowers-skill-first-orchestration-methodology" aria-label="Permalink to &quot;Superpowers (skill-first orchestration methodology)&quot;">​</a></h3><p>Superpowers centers on a <strong>skills system</strong> that auto-injects behavioral constraints into coding agents: brainstorm, plan, implement via TDD, review, and finish branch lifecycle.</p><p>Key structural characteristics:</p><ul><li>Composable, reusable <code>SKILL.md</code> playbooks as the core control surface.</li><li>Broad cross-agent portability (Claude, Codex, Cursor, Gemini, OpenCode, Copilot flows documented).</li><li>Strong emphasis on process discipline via mandatory skill usage when relevant.</li><li>Subagent-driven execution with review loops, but generally less hard runtime gating than dedicated hook-enforced systems.</li><li>Evolution strategy includes writing/testing new skills and continuously improving agent behavior via reusable guidance.</li></ul><h2 id="similarities" tabindex="-1">Similarities <a class="header-anchor" href="#similarities" aria-label="Permalink to &quot;Similarities&quot;">​</a></h2><p>Both frameworks converge on several core principles:</p><ul><li><strong>Human-in-the-loop delivery</strong>: both avoid blind autonomous end-to-end coding.</li><li><strong>Plan-before-code behavior</strong>: both push requirements/design clarification before implementation.</li><li><strong>TDD as a norm</strong>: both explicitly favor RED/GREEN cycles and evidence-oriented validation.</li><li><strong>Subagent specialization</strong>: both split work across specialized agents/roles.</li><li><strong>Workflow codification</strong>: both treat agent behavior as a system to be engineered, not ad-hoc prompting.</li><li><strong>Quality gates</strong>: both insert review checkpoints before declaring completion.</li></ul><h2 id="key-differences" tabindex="-1">Key differences <a class="header-anchor" href="#key-differences" aria-label="Permalink to &quot;Key differences&quot;">​</a></h2><h2 id="_1-control-model-hard-gating-vs-normative-discipline" tabindex="-1">1) Control model: hard gating vs normative discipline <a class="header-anchor" href="#_1-control-model-hard-gating-vs-normative-discipline" aria-label="Permalink to &quot;1) Control model: hard gating vs normative discipline&quot;">​</a></h2><ul><li><strong>nWave</strong>: operationally enforces process through DES hooks (phase enforcement, source-write blocking, TDD completeness checks).</li><li><strong>Superpowers</strong>: enforces through instruction architecture and mandatory skill invocation semantics.</li></ul><p>Implication: nWave favors stronger guardrails and consistency; Superpowers favors flexibility and portability.</p><h2 id="_2-process-topology-fixed-pipeline-vs-composable-lifecycle" tabindex="-1">2) Process topology: fixed pipeline vs composable lifecycle <a class="header-anchor" href="#_2-process-topology-fixed-pipeline-vs-composable-lifecycle" aria-label="Permalink to &quot;2) Process topology: fixed pipeline vs composable lifecycle&quot;">​</a></h2><ul><li><strong>nWave</strong>: explicit seven-wave pipeline with prescribed artifact flow and routing logic.</li><li><strong>Superpowers</strong>: canonical workflow exists, but composition is centered on skills that can adapt to context and platform.</li></ul><p>Implication: nWave is easier to standardize as an SDLC; Superpowers is easier to extend/reshape.</p><h2 id="_3-installation-and-platform-posture" tabindex="-1">3) Installation and platform posture <a class="header-anchor" href="#_3-installation-and-platform-posture" aria-label="Permalink to &quot;3) Installation and platform posture&quot;">​</a></h2><ul><li><strong>nWave</strong>: optimized for Claude Code with CLI install to preserve hook-based enforcement; plugin path is documented as degraded.</li><li><strong>Superpowers</strong>: intentionally multi-platform with marketplace/plugin pathways across multiple agent ecosystems.</li></ul><p>Implication: nWave can be stronger where deeply integrated; Superpowers can spread faster across heterogeneous teams.</p><h2 id="_4-governance-mechanics" tabindex="-1">4) Governance mechanics <a class="header-anchor" href="#_4-governance-mechanics" aria-label="Permalink to &quot;4) Governance mechanics&quot;">​</a></h2><ul><li><strong>nWave</strong>: governance is process-embedded via explicit stage controls and enforcement messages.</li><li><strong>Superpowers</strong>: governance is behavior-embedded through skill content and review practices.</li></ul><p>Implication: nWave governance is more system-enforced; Superpowers governance is more culture/instruction-enforced.</p><h2 id="_5-cost-quality-tuning" tabindex="-1">5) Cost-quality tuning <a class="header-anchor" href="#_5-cost-quality-tuning" aria-label="Permalink to &quot;5) Cost-quality tuning&quot;">​</a></h2><ul><li><strong>nWave</strong>: explicit rigor profiles map model/reviewer depth and mutation testing to risk/cost.</li><li><strong>Superpowers</strong>: quality/cost trade-offs are present but less centrally productized as a single runtime control surface.</li></ul><p>Implication: nWave gives clearer operational knobs for budgeted rigor at runtime.</p><h2 id="advantages-and-disadvantages" tabindex="-1">Advantages and disadvantages <a class="header-anchor" href="#advantages-and-disadvantages" aria-label="Permalink to &quot;Advantages and disadvantages&quot;">​</a></h2><h3 id="nwave-advantages" tabindex="-1">nWave advantages <a class="header-anchor" href="#nwave-advantages" aria-label="Permalink to &quot;nWave advantages&quot;">​</a></h3><ul><li>Strong execution reliability from hook-based phase enforcement.</li><li>Clear SDLC decomposition useful for teams needing predictable handoffs.</li><li>Explicit quality/cost profile controls support risk-tiered delivery.</li><li>Rich artifact trail improves auditability and governance.</li></ul><h3 id="nwave-disadvantages" tabindex="-1">nWave disadvantages <a class="header-anchor" href="#nwave-disadvantages" aria-label="Permalink to &quot;nWave disadvantages&quot;">​</a></h3><ul><li>Higher process overhead for small changes or rapid spikes.</li><li>Greater onboarding complexity (commands, waves, DES behavior, install method nuances).</li><li>Dependency on environment-specific enforcement features can reduce portability.</li><li>Potential rigidity if team context needs non-standard sequencing.</li></ul><h3 id="superpowers-advantages" tabindex="-1">Superpowers advantages <a class="header-anchor" href="#superpowers-advantages" aria-label="Permalink to &quot;Superpowers advantages&quot;">​</a></h3><ul><li>High portability across coding-agent ecosystems.</li><li>Modular skill architecture enables rapid methodology evolution.</li><li>Strong emphasis on planning, TDD, and review without requiring a single fixed pipeline.</li><li>Easier incremental adoption (teams can adopt selected skills first).</li></ul><h3 id="superpowers-disadvantages" tabindex="-1">Superpowers disadvantages <a class="header-anchor" href="#superpowers-disadvantages" aria-label="Permalink to &quot;Superpowers disadvantages&quot;">​</a></h3><ul><li>Consistency can vary more by model/toolchain and prompt-compliance quality.</li><li>Weaker hard-runtime gating compared with hook-enforced frameworks.</li><li>Skill sprawl and instruction interactions can introduce governance drift over time.</li><li>Requires disciplined maintenance of skill quality to avoid stale or conflicting guidance.</li></ul><h2 id="best-fit-scenarios" tabindex="-1">Best-fit scenarios <a class="header-anchor" href="#best-fit-scenarios" aria-label="Permalink to &quot;Best-fit scenarios&quot;">​</a></h2><h3 id="choose-nwave-when" tabindex="-1">Choose nWave when <a class="header-anchor" href="#choose-nwave-when" aria-label="Permalink to &quot;Choose nWave when&quot;">​</a></h3><ul><li>You need strict process control and auditable stage gates.</li><li>You are operating in higher-risk domains where quality enforcement must be difficult to bypass.</li><li>Your team can accept higher ceremony for predictability and compliance.</li></ul><h3 id="choose-superpowers-when" tabindex="-1">Choose Superpowers when <a class="header-anchor" href="#choose-superpowers-when" aria-label="Permalink to &quot;Choose Superpowers when&quot;">​</a></h3><ul><li>You need a portable methodology across multiple agent platforms.</li><li>You value adaptable playbooks and gradual adoption over fixed pipeline standardization.</li><li>Your teams are mature enough to follow norms without relying on hard hook-level constraints.</li></ul><h2 id="research-conclusion" tabindex="-1">Research conclusion <a class="header-anchor" href="#research-conclusion" aria-label="Permalink to &quot;Research conclusion&quot;">​</a></h2><p>Both approaches share a mature view of agentic development: structured workflows, explicit quality practices, and human approval points. The major divergence is <strong>how control is implemented</strong>:</p><ul><li><code>nWave</code> is <strong>pipeline-and-enforcement heavy</strong> (operational rigor first).</li><li><code>Superpowers</code> is <strong>skill-and-portability heavy</strong> (methodological adaptability first).</li></ul><p>For technical leadership, the decision is less &quot;which is better&quot; and more &quot;which governance posture matches your org&quot;:</p><ul><li>If you optimize for compliance-grade repeatability, nWave is stronger.</li><li>If you optimize for cross-platform velocity and evolving practice, Superpowers is stronger.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>nWave repository: <a href="https://github.com/nWave-ai/nWave/tree/main" target="_blank" rel="noreferrer">https://github.com/nWave-ai/nWave/tree/main</a></li><li>nWave project site: <a href="https://nwave.ai" target="_blank" rel="noreferrer">https://nwave.ai</a></li><li>Superpowers repository: <a href="https://github.com/obra/superpowers" target="_blank" rel="noreferrer">https://github.com/obra/superpowers</a></li><li>Superpowers launch article: <a href="https://blog.fsck.com/2025/10/09/superpowers/" target="_blank" rel="noreferrer">https://blog.fsck.com/2025/10/09/superpowers/</a></li></ul>',57)])])}const g=a(t,[["render",n]]);export{u as __pageData,g as default};
